const C=InnoviaCatalog,grid=document.getElementById('prototype-grid'),form=document.getElementById('prototype-form'),questions=document.getElementById('practice-questions'),note=document.getElementById('prototype-message');
let activeId=null,busy=false;
function question(value={title:'',choices:['','','',''],correct:0,explain:''}) {
  const block=document.createElement('fieldset');block.className='practice-question';
  const legend=document.createElement('legend');legend.textContent='練習問題';block.append(legend);
  const title=document.createElement('textarea');title.className='input';title.dataset.field='title';title.placeholder='問題文';title.setAttribute('aria-label','問題文');title.required=true;title.maxLength=1000;title.value=value.title;block.append(title);
  value.choices.forEach((choice,index)=>{const label=document.createElement('label');label.className='input-label';label.textContent='選択肢 '+String(index+1);const input=document.createElement('input');input.className='input';input.dataset.choice=String(index);input.required=true;input.maxLength=200;input.value=choice;label.append(input);block.append(label);});
  const correctLabel=document.createElement('label');correctLabel.className='input-label';correctLabel.textContent='正解';const correct=document.createElement('select');correct.className='input';correct.dataset.field='correct';for(let i=0;i<4;i++){const option=document.createElement('option');option.value=String(i);option.textContent='選択肢 '+String(i+1);correct.append(option);}correct.value=String(value.correct);correctLabel.append(correct);block.append(correctLabel);
  const explain=document.createElement('textarea');explain.className='input';explain.dataset.field='explain';explain.placeholder='解説（任意）';explain.setAttribute('aria-label','解説');explain.maxLength=1000;explain.value=value.explain;block.append(explain);questions.append(block);
}
function switchKind(){const quiz=form.elements.kind.value==='quiz';document.getElementById('link-fields').hidden=quiz;document.getElementById('quiz-fields').hidden=!quiz;form.elements.href.required=!quiz;for(const input of questions.querySelectorAll('input,textarea,select'))input.disabled=!quiz;}
form.elements.kind.onchange=switchKind;
document.getElementById('add-question').onclick=()=>{if(questions.children.length<20)question();};
document.getElementById('new-prototype').onclick=()=>{activeId=null;form.reset();questions.replaceChildren();question();switchKind();note.textContent='新しい試作を入力してください。';form.elements.title.focus();};
async function edit(item){try{const result=await C.api('get',{id:item.id,preview:true},true);activeId=item.id;form.elements.title.value=result.material.title;form.elements.description.value=result.material.description;form.elements.kind.value=result.material.kind;form.elements.href.value=result.material.href||'';questions.replaceChildren();for(const q of result.material.questions||[{title:'',choices:['','','',''],correct:0,explain:''}])question(q);switchKind();form.elements.title.focus();note.textContent='編集内容は試作として保存され、生徒側は「生徒用に追加」を押すまで変わりません。';}catch(error){note.textContent=error.message;}}
async function refresh(){const data=await C.api('preview',{},true);if(!C.valid(data))throw Error('試作の一覧を読み込めませんでした。');grid.replaceChildren();for(const item of data.materials){const entry=document.createElement('div');entry.className='prototype-entry';entry.append(C.card(item,true));const status=document.createElement('p');status.className='small-note';status.textContent=item.id==='network'&&!data.networkVisible?'生徒用は非公開':item.published?(item.revision===item.publishedRevision?'生徒用に公開済み':'公開済み・試作の変更は未反映'):'試作・先生のみ';entry.append(status);if(!item.builtin){const controls=document.createElement('div');controls.className='actions';const editButton=document.createElement('button');editButton.type='button';editButton.className='ghost';editButton.textContent='試作を編集';editButton.onclick=()=>edit(item);const publish=document.createElement('button');publish.type='button';publish.className='button';publish.textContent=item.published?'確認した変更を生徒用に反映':'生徒用に追加';publish.disabled=true;const label=document.createElement('label');const check=document.createElement('input');check.type='checkbox';check.onchange=()=>{publish.disabled=!check.checked;};label.append(check,document.createTextNode(' 試して内容を確認しました'));publish.onclick=async()=>{publish.disabled=true;check.disabled=true;try{await C.api('publish',{id:item.id,revision:item.revision},true);note.textContent='生徒用の教材一覧に追加しました。';await refresh();}catch(error){note.textContent=error.message;publish.disabled=false;check.disabled=false;}};entry.append(label);controls.append(editButton,publish);entry.append(controls);}grid.append(entry);}}
form.onsubmit=async event=>{event.preventDefault();if(busy)return;const payload={id:activeId,title:form.elements.title.value.trim(),description:form.elements.description.value.trim(),kind:form.elements.kind.value,href:form.elements.href.value.trim()};if(payload.kind==='quiz')payload.questions=[...questions.children].map(block=>({title:block.querySelector('[data-field="title"]').value.trim(),choices:[...block.querySelectorAll('[data-choice]')].map(input=>input.value.trim()),correct:Number(block.querySelector('[data-field="correct"]').value),explain:block.querySelector('[data-field="explain"]').value.trim()}));busy=true;form.querySelector('[type=submit]').disabled=true;try{const result=await C.api('save',payload,true);activeId=result.id;note.textContent='試作を保存しました。カードから試し、確認できたら「生徒用に追加」を押してください。';await refresh();}catch(error){note.textContent=error.message;}finally{busy=false;form.querySelector('[type=submit]').disabled=false;}};
question();switchKind();(async()=>{try{if(await C.teacherGuard())await refresh();}catch(error){document.getElementById('guard-message').textContent=error.message;}})();
